package com.cyberpath.learning;
import android.app.Activity;
import android.speech.tts.TextToSpeech;
import android.speech.tts.UtteranceProgressListener;
import android.speech.tts.Voice;
import org.json.*;
import java.util.*;
import java.util.function.Consumer;
/** Explicit read-aloud using installed voices that do not require a network. */
public final class LocalSpeech {
 private final Activity activity;private final Consumer<String> emit;private TextToSpeech engine;private volatile boolean ready=false,closed=false;private volatile String status="{\"ready\":false,\"voices\":[]}",lastUtterance="";private final Map<String,Voice> voices=new HashMap<>();private volatile int generation=0;
 public LocalSpeech(Activity activity,Consumer<String> emit){this.activity=activity;this.emit=emit;engine=new TextToSpeech(activity,result->new android.os.Handler(android.os.Looper.getMainLooper()).post(()->initialized(result)));}
 private void initialized(int result){if(closed)return;ready=result==TextToSpeech.SUCCESS;if(ready){refresh();engine.setOnUtteranceProgressListener(new UtteranceProgressListener(){@Override public void onStart(String id){}@Override public void onDone(String id){activity.runOnUiThread(()->{if(id.equals(lastUtterance))event("idle","");});}@Override public void onError(String id){activity.runOnUiThread(()->{if(id.startsWith("lw-"+generation+"-")){stop();event("error","The installed voice could not read this passage.");}});}});}else{status="{\"ready\":true,\"voices\":[],\"error\":\"No offline speech engine is available.\"}";}event("ready","");}
 private void event(String state,String error){try{emit.accept(new JSONObject().put("state",state).put("error",error).toString());}catch(Exception ignored){}}
 private void refresh(){try{JSONArray rows=new JSONArray();voices.clear();Set<Voice> available=engine.getVoices();Voice defaultVoice=engine.getVoice();if(available!=null)for(Voice voice:available){if(voice.isNetworkConnectionRequired()||voice.getFeatures()!=null&&voice.getFeatures().contains(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED))continue;voices.put(voice.getName(),voice);rows.put(new JSONObject().put("id",voice.getName()).put("name",voice.getName()).put("language",voice.getLocale().toLanguageTag()).put("default",defaultVoice!=null&&voice.getName().equals(defaultVoice.getName())));}status=new JSONObject().put("ready",true).put("voices",rows).toString();}catch(Exception e){status="{\"ready\":true,\"voices\":[],\"error\":\"Offline voices could not be listed.\"}";}}
 public String voices(){return status;}
 public void refreshVoices(){if(ready&&!closed){refresh();event("ready","");}}
 public void speak(String raw){try{if(!ready||closed)throw new IllegalStateException("Offline voices are still loading. Try again.");JSONObject request=new JSONObject(raw);String text=request.getString("text"),name=request.getString("voice");double rate=request.optDouble("rate",1);if(text.trim().isEmpty()||text.length()>100000||rate<.5||rate>2||!Double.isFinite(rate))throw new IllegalArgumentException("Choose a valid passage and speed.");Voice voice=voices.get(name);if(voice==null||voice.isNetworkConnectionRequired())throw new IllegalArgumentException("Choose an installed offline voice.");stop();if(engine.setVoice(voice)!=TextToSpeech.SUCCESS||engine.setSpeechRate((float)rate)!=TextToSpeech.SUCCESS)throw new IllegalStateException("This offline voice is unavailable.");List<String> chunks=chunks(text,Math.min(3000,TextToSpeech.getMaxSpeechInputLength()-1));String prefix="lw-"+generation+"-";lastUtterance=prefix+(chunks.size()-1);event("speaking","");for(int i=0;i<chunks.size();i++)if(engine.speak(chunks.get(i),i==0?TextToSpeech.QUEUE_FLUSH:TextToSpeech.QUEUE_ADD,new android.os.Bundle(),prefix+i)==TextToSpeech.ERROR)throw new IllegalStateException("The installed voice could not start.");}catch(Exception e){stop();event("error",e.getMessage());}}
 static List<String> chunks(String source,int limit){List<String> output=new ArrayList<>();String rest=source.trim();while(rest.length()>limit){int at=Math.max(rest.lastIndexOf('\n',limit),Math.max(rest.lastIndexOf(". ",limit-1)+1,rest.lastIndexOf("। ",limit-1)+1));if(at<limit/2)at=rest.lastIndexOf(' ',limit);if(at<limit/2)at=limit;if(Character.isHighSurrogate(rest.charAt(at-1)))at--;output.add(rest.substring(0,at).trim());rest=rest.substring(at).trim();}if(!rest.isEmpty())output.add(rest);return output;}
 public void stop(){generation++;lastUtterance="";if(engine!=null)engine.stop();event("idle","");}
 public void close(){closed=true;stop();if(engine!=null){engine.shutdown();engine=null;}voices.clear();}
}
